#define ZOOM 7.0f

void mainImage(out vec4 colour, in vec2 coord) {

    vec2 pos = (coord / iResolution.y) * ZOOM;

    vec2 cell_id = floor(pos);
    pos = fract(pos);

    pos.y += (-1.0f * mod(cell_id.y, 2.0f)) + 0.25f * ceil(cell_id.y / 2.0f);

    float radius = 0.5f;
    float half_spacing = 0.0f;

    vec2 s = vec2(2.0f, 7.0f/4.0f * 2.0f) * (radius + half_spacing);

    vec2 position = pos / s;

    vec2 d1 = (fract(position) - 0.5f) * s;
    vec2 d2 = (fract(position + 0.5f) - 0.5f) * s;
    float d = sqrt(min(dot(d1, d1), dot(d2, d2))) - radius;

    colour = vec4(sign(d));
}
